export interface AppStep { title: string; desc: string; }
export interface AppProto {
  emoji: string; price: string; name: string; desc: string;
  categoria: string; tags: string[];
  paraQuem: { title: string; desc: string };
  problema: string; solucao: string; impacto: string;
  comoFunciona: AppStep[];
  sugestoesNome: string[];
  prompt: string;
}

function buildPrompt(a: Omit<AppProto,"prompt">): string {
  const steps = a.comoFunciona.map((s,i) => `${i+1}. ${s.title}: ${s.desc}`).join("\n");
  return [
    `Você é um Engenheiro de Software Sênior e especialista em UX/UI. Sua missão é criar um micro-SaaS de alta qualidade chamado "${a.name}" usando React e TailwindCSS, pronto para apresentar a clientes reais.`,
    `\n═══ PRODUTO ═══\nNome: ${a.name}\nProposta: ${a.desc}\nPara quem: ${a.paraQuem.title}. ${a.paraQuem.desc}\nProblema: ${a.problema}\nSolução: ${a.solucao}\nImpacto: ${a.impacto}\nPreço: ${a.price}\nCategoria: ${a.categoria}`,
    `\n═══ FLUXO ═══\n${steps}`,
    `\n═══ TELAS OBRIGATÓRIAS ═══\n1. LANDING PAGE: Hero com headline, benefícios em 3 cards, "Como funciona" visual, seção de preços (2 planos), CTA final, botão WhatsApp flutuante, footer.\n2. LOGIN/CADASTRO: Email+senha, alternância login/cadastro, validação visual.\n3. DASHBOARD: Header com usuário, sidebar colapsável, 4 métricas com trend indicator, gráfico últimos 6 meses (SVG ou recharts), tabela últimos 8 registros com badges de status.\n4. TELA CORE: Listagem com busca/filtros/ordenação, botão Novo abre modal com formulário completo, estados: vazio/carregando/dados/erro, badges coloridos (ativo/pendente/concluído/cancelado).\n5. CONFIGURAÇÕES: Perfil da empresa, configurações específicas do produto, notificações por toggle.`,
    `\n═══ DESIGN ═══\nDark mode: fundo #0A0A0A, cards #111218, bordas rgba(255,255,255,0.08). Cor de destaque vibrante coesa com "${a.categoria}". Fonte Inter do Google Fonts. Espaçamento sistema 8px. Ícones somente lucide-react. Bordas retas (max rounded-lg). Hover/focus/active em todos os elementos. transition-all duration-200.`,
    `\n═══ REGRAS ═══\nReact + TailwindCSS puro (sem shadcn/antd/mui). Componentes reutilizáveis: Sidebar, Header, MetricCard, DataTable, StatusBadge, Modal, EmptyState. useState para: usuário, tela ativa, modal, listagem. Dados mockados REALISTAS: nomes brasileiros, R$, DD/MM/AAAA, coerentes com "${a.paraQuem.title}". SEM backend, SEM API, SEM banco. App 100% funcional no frontend. Mobile-first: sidebar vira drawer em telas pequenas. Mínimo 8 registros mockados com status variados.\n\nComece pela estrutura de componentes e pelo Dashboard principal.`
  ].join("");
}

