export const appsProntos: AppProto[] = raw.map(a => ({ 
  ...a, 
  categoria: categoryMap[a.categoria] || a.categoria,
  prompt: buildPrompt({ ...a, categoria: categoryMap[a.categoria] || a.categoria }) 
}));

export const getTagDotColor = (tag: string): string => {
  if (tag === "Publico quente") return "bg-orange-500";
  if (tag === "Facil de fazer") return "bg-emerald-500";
  if (tag === "Em alta") return "bg-blue-500";
  if (tag === "Alto valor percebido") return "bg-purple-500";
  if (tag === "Nicho especifico") return "bg-pink-500";
  return "bg-gray-500";
};
